from pysat.solvers import Solver
from pysat.card import CardEnc
from pysat.formula import CNF

n = 10

def var(u, v):
    if u > v:
        u, v = v, u
    idx = 0
    for i in range(u):
        idx += n - 1 - i
    idx += v - u
    return idx

fixed_edges = [(8,9), (2,8), (2,7), (2,9), (0,1), (0,8), (1,8), (3,8), (5,8)]

cnf = CNF()

for u, v in fixed_edges:
    cnf.append([var(u, v)])

# Min degree >= 4
for i in range(n):
    incident_vars = []
    for j in range(n):
        if i != j:
            incident_vars.append(var(i, j))

    # sum >= 4
    clauses = CardEnc.atleast(lits=incident_vars, bound=4, vpool=None)
    for clause in clauses.clauses:
        cnf.append(clause)

with Solver(name='g3') as s:
    s.append_formula(cnf.clauses)
    if s.solve():
        model = s.get_model()
        edges = []
        for u in range(n):
            for v in range(u+1, n):
                if model[var(u, v) - 1] > 0:
                    edges.append([u, v])
        print("SAT")
        print(edges)
    else:
        print("UNSAT")
